/* Shim versions of the few xscreensaver utils helpers that hacks call.
 * Written for this project; not derived from xscreensaver's utils. */
#include <stdlib.h>

#include "colors.h"
#include "erase.h"
#include "hsv.h"

static double frand_unit(void) {
  return (double)random() / ((double)RAND_MAX + 1.0);
}

/* No wipe animation: clear the window and report that erasing is done. */
eraser_state *erase_window(Display *dpy, Window w, eraser_state *st) {
  (void)st;
  XClearWindow(dpy, w);
  return NULL;
}

void eraser_free(eraser_state *st) { (void)st; }

void make_random_colormap(Screen *screen, Visual *visual, Colormap cmap,
                          XColor *colors, int *ncolorsP, Bool bright_p,
                          Bool allocate_p, Bool *writable_pP, Bool verbose_p) {
  (void)screen;
  (void)visual;
  (void)cmap;
  (void)allocate_p;
  (void)verbose_p;
  if (writable_pP) *writable_pP = False;
  for (int i = 0; i < *ncolorsP; i++) {
    double s = bright_p ? 0.6 + frand_unit() * 0.4 : 0.2 + frand_unit() * 0.8;
    double v = bright_p ? 0.8 + frand_unit() * 0.2 : 0.5 + frand_unit() * 0.5;
    hsv_to_rgb((int)(frand_unit() * 360), s, v, &colors[i].red,
               &colors[i].green, &colors[i].blue);
    colors[i].flags = DoRed | DoGreen | DoBlue;
    colors[i].pixel = rgb565_from16(colors[i].red, colors[i].green, colors[i].blue);
  }
}
#include <stdlib.h>
#include <string.h>
#include <unity.h>

#include "core/canvas.h"
#include "hacks/registry.h"
#include "runner/hack_runner.h"

static Canvas cv;

void setUp(void) { TEST_ASSERT_EQUAL_INT(0, canvas_init(&cv, 466, 466, malloc)); }
void tearDown(void) { canvas_free(&cv); }

static int non_black(void) {
  int n = 0;
  for (long i = 0; i < (long)cv.w * cv.h; i++) n += cv.px[i] != 0;
  return n;
}

void test_registry_lists_hacks_in_order(void) {
  static const char *const expected[] = {"Pyro", "HyperCube", "XSpirograph",
                                         "Petri", "Helix"};
  TEST_ASSERT_EQUAL_INT(5, g_hack_count);
  for (int i = 0; i < 5; i++) TEST_ASSERT_EQUAL_STRING(expected[i], g_hacks[i]->name);
}

void test_every_hack_draws_something_within_2000_frames(void) {
  for (int i = 0; i < g_hack_count; i++) {
    HackRunner *r = runner_create(&cv);
    TEST_ASSERT_EQUAL_INT(0, runner_start(r, i));
    int seen = 0;
    for (int f = 0; f < 2000 && !seen; f++) {
      runner_step(r);
      seen = non_black() >= 20;
    }
    TEST_ASSERT_TRUE_MESSAGE(seen, g_hacks[i]->name);
    runner_destroy(r);
  }
}

void test_every_hack_runs_3000_frames_cleanly_with_sane_delays(void) {
  for (int i = 0; i < g_hack_count; i++) {
    HackRunner *r = runner_create(&cv);
    runner_start(r, i);
    for (int f = 0; f < 3000; f++) {
      unsigned long d = runner_step(r);
      TEST_ASSERT_TRUE_MESSAGE(d >= RUNNER_MIN_DELAY_US && d <= RUNNER_MAX_DELAY_US,
                               g_hacks[i]->name);
    }
    runner_destroy(r);
  }
}

void test_cycling_through_all_hacks_100_times_is_asan_clean(void) {
  HackRunner *r = runner_create(&cv);
  runner_start(r, 0);
  for (int i = 0; i < 100; i++) {
    for (int s = 0; s < 5; s++) runner_step(r);
    runner_next(r);
  }
  TEST_ASSERT_EQUAL_INT(100 % g_hack_count, runner_index(r));
  runner_destroy(r);
}

void test_prev_from_first_wraps_to_last_hack(void) {
  HackRunner *r = runner_create(&cv);
  runner_start(r, 0);
  TEST_ASSERT_EQUAL_INT(g_hack_count - 1, runner_prev(r));
  runner_step(r);
  runner_destroy(r);
}

int main(void) {
  UNITY_BEGIN();
  RUN_TEST(test_registry_lists_hacks_in_order);
  RUN_TEST(test_every_hack_draws_something_within_2000_frames);
  RUN_TEST(test_every_hack_runs_3000_frames_cleanly_with_sane_delays);
  RUN_TEST(test_cycling_through_all_hacks_100_times_is_asan_clean);
  RUN_TEST(test_prev_from_first_wraps_to_last_hack);
  return UNITY_END();
}
